package com.tracksphere.application.attendance;
import com.tracksphere.application.attendance.dto.AttendanceResponse; import com.tracksphere.domain.model.*; import com.tracksphere.domain.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class AttendanceService { private final AttendanceRepository attendance; private final UserRepository users; public AttendanceResponse clockIn(UUID userId){if(attendance.findFirstByUserIdAndClockOutIsNullOrderByClockInDesc(userId).isPresent())throw new IllegalStateException("You are already clocked in");User user=users.findById(userId).orElseThrow();return map(attendance.save(new AttendanceRecord(user)));} public AttendanceResponse clockOut(UUID userId){AttendanceRecord r=attendance.findFirstByUserIdAndClockOutIsNullOrderByClockInDesc(userId).orElseThrow(()->new IllegalStateException("No active clock-in found"));r.clockOut();return map(r);}@Transactional(readOnly=true) public Optional<AttendanceResponse> today(UUID userId){return attendance.findFirstByUserIdAndClockOutIsNullOrderByClockInDesc(userId).map(this::map);}@Transactional(readOnly=true) public List<AttendanceResponse> report(Instant from,Instant to,String search){String q=search==null?"":search.toLowerCase();return attendance.findByClockInBetweenOrderByClockInDesc(from==null?Instant.EPOCH:from,to==null?Instant.now():to).stream().map(this::map).filter(r->q.isBlank()||r.employeeName().toLowerCase().contains(q)||r.email().toLowerCase().contains(q)).toList();}private AttendanceResponse map(AttendanceRecord r){Long minutes=r.getClockOut()==null?null:Duration.between(r.getClockIn(),r.getClockOut()).toMinutes();User u=r.getUser();return new AttendanceResponse(r.getId(),u.getId(),u.getFirstName()+" "+u.getLastName(),u.getEmail(),r.getClockIn(),r.getClockOut(),minutes);} }
